files.purpose:
Imports json, uuid, datetime; Claim, Policy, Appeal, DenialReason, AppealStrength, Contradiction from models.jac; and extract_denial_reason, extract_relevant_clauses, find_contradictions, assess_appeal_strength, draft_appeal_letter from tools.jac. submit_claim on Root entry: builds Claim(claim_id=claim_number, patient_name, member_id, cpt_code, date_of_service, billed_amount, denial_text, clinical_record) and Policy(policy_id=f"POL-{member_id}", plan_name, full_text=policy_text), connects both to here (root); then calls in this order reason = extract_denial_reason(denial_text), clauses = extract_relevant_clauses(policy_text, reason), contradictions = find_contradictions(denial_text, clinical_record, clauses), strength = assess_appeal_strength(contradictions), letter = draft_appeal_letter(...all claim fields, plan_name, denial_reason=reason, contradictions, clinical_record); then connects Appeal(appeal_id=f"APL-{uuid.uuid4().hex[:8]}", claim_id, policy_id, denial_reason=reason, strength, contradictions_json=json.dumps of a list of dicts with keys denial_quote, policy_quote, clause_section, explanation, letter_subject=letter.subject, letter_body=f"{letter.salutation}

{letter.body}

{letter.closing}", citations_json=json.dumps(letter.citations), created_at=datetime.datetime.utcnow().isoformat()) to root and reports exactly one dict {appeal_id, claim_id, subject: letter.subject, letter: appeal.letter_body, citations: letter.citations}. list_appeals on Root entry collects [-->[?:Appeal]] and reports ONE list whose rows are dicts {appeal_id, claim_id, subject: letter_subject, created_at}.
